create table public.character_stamina(character_id uuid primary key references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,dimension_id uuid not null references public.dimension_presets(id),current_stamina smallint not null default 100 check(current_stamina between 0 and 100),max_stamina smallint not null default 100 check(max_stamina=100),fatigue_level text not null default'fresh'check(fatigue_level in('fresh','weary','exhausted')),updated_at timestamptz not null default now());
create table public.stamina_ledger(id uuid primary key default gen_random_uuid(),character_id uuid not null references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,delta smallint not null check(delta<>0),stamina_after smallint not null check(stamina_after between 0 and 100),reason text not null check(char_length(reason)between 2 and 80),created_at timestamptz not null default now());
alter table public.character_stamina enable row level security;alter table public.stamina_ledger enable row level security;
create policy "Players read own stamina"on public.character_stamina for select to authenticated using(user_id=auth.uid());create policy "Players read own stamina ledger"on public.stamina_ledger for select to authenticated using(user_id=auth.uid());
create or replace function public.get_character_stamina(target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare hero public.characters%rowtype;preset public.dimension_presets%rowtype;state public.character_stamina%rowtype;enabled boolean;begin select*into hero from public.characters where id=target_character_id and user_id=auth.uid();if hero.id is null then raise exception'character not found';end if;select*into preset from public.dimension_presets where id=hero.dimension_id;enabled:=coalesce((preset.rules_config->>'stamina')::boolean,false);if not enabled then return jsonb_build_object('enabled',false,'dimension_id',hero.dimension_id);end if;insert into public.character_stamina(character_id,user_id,dimension_id)values(hero.id,hero.user_id,hero.dimension_id)on conflict(character_id)do nothing;select*into state from public.character_stamina where character_id=hero.id;return jsonb_build_object('enabled',true,'current',state.current_stamina,'max',state.max_stamina,'fatigue_level',state.fatigue_level,'dimension_id',state.dimension_id);end;$$;
create or replace function public.change_character_stamina(target_character_id uuid,target_delta integer,target_reason text)returns jsonb language plpgsql security definer set search_path=''as $$declare context jsonb;state public.character_stamina%rowtype;next_value integer;clean_reason text;begin context:=public.get_character_stamina(target_character_id);if not coalesce((context->>'enabled')::boolean,false)then raise exception'stamina disabled';end if;if target_delta=0 or abs(target_delta)>100 then raise exception'invalid delta';end if;clean_reason:=left(regexp_replace(trim(target_reason),'\s+',' ','g'),80);if char_length(clean_reason)<2 then raise exception'invalid reason';end if;select*into state from public.character_stamina where character_id=target_character_id and user_id=auth.uid()for update;next_value:=state.current_stamina+target_delta;if next_value<0 then raise exception'insufficient stamina';end if;next_value:=least(state.max_stamina,next_value);update public.character_stamina set current_stamina=next_value,fatigue_level=case when next_value<=20 then'exhausted'when next_value<=50 then'weary'else'fresh'end,updated_at=now()where character_id=state.character_id returning*into state;insert into public.stamina_ledger(character_id,user_id,delta,stamina_after,reason)values(state.character_id,state.user_id,target_delta,state.current_stamina,clean_reason);return jsonb_build_object('enabled',true,'current',state.current_stamina,'max',state.max_stamina,'fatigue_level',state.fatigue_level,'dimension_id',state.dimension_id);end;$$;
revoke all on function public.get_character_stamina(uuid)from public;revoke all on function public.change_character_stamina(uuid,integer,text)from public;grant execute on function public.get_character_stamina(uuid)to authenticated;grant execute on function public.change_character_stamina(uuid,integer,text)to authenticated;
